// SQLiteStorage implements the Storage interface using SQLite
type SQLiteStorage struct {
	db           *sql.DB
	embeddingDim int
	mu           sync.RWMutex
	closed       bool
}

func TestGetToolDefinitions_EverySchemaIsAValidObjectSchema(t *testing.T) {
	// InputSchema is shipped to the client as raw JSON. Anything that is not a
	// well-formed object schema either fails validation at the client or lets a
	// malformed argument map through to the CLI.
	for _, tool := range GetToolDefinitions() {
		t.Run(tool.Name, func(t *testing.T) {
			var schema struct {
				Type       string                     `json:"type"`
				Properties map[string]json.RawMessage `json:"properties"`
				Required   []string                   `json:"required"`
			}
			if err := json.Unmarshal(tool.InputSchema, &schema); err != nil {
				t.Fatalf("InputSchema is not valid JSON: %v\n%s", err, tool.InputSchema)
			}
			if schema.Type != "object" {
				t.Errorf(`schema type = %q, want "object"`, schema.Type)
			}
			if schema.Properties == nil {
				t.Errorf("schema declares no properties: %s", tool.InputSchema)
			}
			// Anything listed as required must actually be a declared property,
			// or the client rejects every call to the tool.
			for _, req := range schema.Required {
				if _, ok := schema.Properties[req]; !ok {
					t.Errorf("required field %q is not a declared property", req)
				}
			}
			// Every property must itself declare a type, which is what the
			// client uses to coerce the model's arguments.
			for name, raw := range schema.Properties {
				var prop struct {
					Type string `json:"type"`
				}
				if err := json.Unmarshal(raw, &prop); err != nil {
					t.Fatalf("property %q is not valid JSON: %v", name, err)
				}
				if prop.Type == "" {
					t.Errorf("property %q declares no type: %s", name, raw)
				}
			}
		})
	}
}

// buildSchema creates a JSON Schema object with merged properties.
func buildSchema(toolProps map[string]schemaProperty, required []string) json.RawMessage {
	props := mergeProperties(toolProps, commonProperties())
	schema := map[string]interface{}{
		"type":       "object",
		"properties": props,
	}
	if len(required) > 0 {
		schema["required"] = required
	}
	data, _ := json.Marshal(schema)
	return data
}

// NewSQLiteStorage creates a new SQLite-based storage
func NewSQLiteStorage(dbPath string, embeddingDim int) (*SQLiteStorage, error) {
	if dbPath == "" {
		dbPath = ":memory:"
	}

	// Ensure parent directory exists for file-based databases
	if dbPath != ":memory:" {
		dir := filepath.Dir(dbPath)
		if err := os.MkdirAll(dir, 0755); err != nil {
			return nil, fmt.Errorf("failed to create database directory: %w", err)
		}
	}

	db, err := sql.Open("sqlite", dbPath)
	if err != nil {
		return nil, fmt.Errorf("failed to open database: %w", err)
	}

	// Enable WAL mode for better concurrent access
	if _, err := db.Exec("PRAGMA journal_mode=WAL"); err != nil {
		db.Close()
		return nil, fmt.Errorf("failed to enable WAL mode: %w", err)
	}

	storage := &SQLiteStorage{
		db:           db,
		embeddingDim: embeddingDim,
	}

	if err := storage.initSchema(); err != nil {
		db.Close()
		return nil, fmt.Errorf("failed to initialize schema: %w", err)
	}

	return storage, nil
}

// initChunkRefsSchema creates the chunk_refs table for dependency/call graph tracking.
func (s *SQLiteStorage) initChunkRefsSchema() error {
	return initChunkRefsTables(s.db)
}

// mergeProperties combines tool-specific properties with common properties.
// Common properties can be overridden by tool-specific ones.
func mergeProperties(toolProps, common map[string]schemaProperty) map[string]schemaProperty {
	result := make(map[string]schemaProperty)
	for k, v := range common {
		result[k] = v
	}
	for k, v := range toolProps {
		result[k] = v
	}
	return result
}

// TestMemoryFileContent_ShortCreatedAt pins that a CreatedAt shorter than a full date is
// passed through verbatim rather than panicking on the [:10] slice.
func TestMemoryFileContent_ShortCreatedAt(t *testing.T) {
	entry := &MemoryEntry{Question: "q", Answer: "a", CreatedAt: "2026"}
	got := entry.MemoryFileContent()
	if !strings.Contains(got, "created: 2026\n") {
		t.Errorf("short CreatedAt should pass through unchanged, got:\n%s", got)
	}
}

// createTestSQLiteStorage creates an in-memory SQLite storage for testing.
func createTestSQLiteStorage(t *testing.T) (*SQLiteStorage, func()) {
	t.Helper()
	storage, err := NewSQLiteStorage(":memory:", 0)
	if err != nil {
		t.Fatalf("Failed to create test storage: %v", err)
	}
	return storage, func() { storage.Close() }
}

func TestServer_EveryAdvertisedSchemaSurvivesTheRoundTrip(t *testing.T) {
	// main() passes InputSchema through as raw JSON. Anything malformed would be
	// rejected or flattened by the SDK on the way out, so this checks what the
	// client actually receives rather than what the definitions hold.
	fakeCLI(t, "{}")
	session := startServer(t).session

	ctx, cancel := context.WithTimeout(context.Background(), 20*time.Second)
	defer cancel()

	res, err := session.ListTools(ctx, nil)
	if err != nil {
		t.Fatalf("ListTools: %v", err)
	}
	for _, tool := range res.Tools {
		if tool.InputSchema == nil {
			t.Errorf("tool %q arrived with no input schema", tool.Name)
			continue
		}
		raw, err := json.Marshal(tool.InputSchema)
		if err != nil {
			t.Errorf("tool %q schema will not re-marshal: %v", tool.Name, err)
			continue
		}
		var schema struct {
			Type       string                     `json:"type"`
			Properties map[string]json.RawMessage `json:"properties"`
		}
		if err := json.Unmarshal(raw, &schema); err != nil {
			t.Errorf("tool %q schema is not a JSON object: %v", tool.Name, err)
			continue
		}
		if schema.Type != "object" {
			t.Errorf(`tool %q schema type = %q, want "object"`, tool.Name, schema.Type)
		}
		if len(schema.Properties) == 0 {
			t.Errorf("tool %q arrived with no properties: %s", tool.Name, raw)
		}
		if strings.TrimSpace(tool.Description) == "" {
			t.Errorf("tool %q arrived with no description", tool.Name)
		}
	}
}

// ToolDefinition defines a tool for the MCP SDK
type ToolDefinition struct {
	Name        string
	Description string
	InputSchema json.RawMessage
}
